package oracle;
import java.io.*;import java.util.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.*;import core.game.node.entity.*;import core.game.node.entity.npc.*;import core.game.node.item.*;import core.game.node.scenery.*;import core.game.world.map.*;import core.game.world.map.path.*;
public class Support {
 static Map input;static Node mover,target;static List<Object> events;static Object invocation;
 public static class Failure extends RuntimeException{}
 static int n(Object v){return((Number)v).intValue();}static int v(Map a,String k,int d){return a.get(k)==null?d:n(a.get(k));}
 static Location loc(Object v){if(v==null)return null;List a=(List)v;return new Location(n(a.get(0)),n(a.get(1)),n(a.get(2)));}
 static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 static void event(String name,Object... args){List<Object> e=new ArrayList<>();e.add(name);e.addAll(Arrays.asList(args));events.add(e);if(name.equals(input.get("mutateAt"))){if(input.containsKey("mutateMover"))mover.location=loc(input.get("mutateMover"));if(input.containsKey("mutateTarget"))target.location=loc(input.get("mutateTarget"));}if(name.equals(input.get("fail")))throw new Failure();}
 static class Supplier implements ClipMaskSupplier{int id;Supplier(int i){id=i;}public int getClippingFlag(int z,int x,int y){return 0;}}
 static ClipMaskSupplier supplier(Object v){return v==null?null:new Supplier(n(v));}
 public static ClipMaskSupplier npc(NPC n){event("npc");return supplier(input.get("npcSupplier"));}
 public static boolean permitted(Location l){event("permitted",coord(l));return !Boolean.FALSE.equals(input.get("permitted"));}
 public static Path invoke(int finder,Location start,int size,Location end,int sx,int sy,int rotation,int kind,int flag,boolean near,ClipMaskSupplier supplier){String mode=(String)input.getOrDefault("mode","entity");Object s=supplier==null?null:supplier instanceof Supplier?((Supplier)supplier).id:mode.equals("water")?"water":"world";invocation=Arrays.asList(finder,coord(start),size,coord(end),sx,sy,rotation,kind,flag,near,s);event("invoke",invocation);Path p=new Path();p.value=invocation;return p;}
 static Node node(Object kind){if(kind==null)return null;switch((String)kind){case"entity":return new Entity();case"npc":return new NPC();case"scenery":return new Scenery();case"item":return new GroundItem();default:return new Node();}}
 static Object evaluate(){mover=node(input.getOrDefault("moverKind","entity"));target=node(input.getOrDefault("targetKind","other"));if(mover!=null){mover.location=loc(input.getOrDefault("start",Arrays.asList(3207L,3216L,0L)));mover.size=v(input,"moverSize",1);if(mover instanceof NPC&&Boolean.FALSE.equals(input.get("behavior")))((NPC)mover).behavior=null;}if(target!=null){target.location=loc(input.getOrDefault("end",Arrays.asList(3210L,3218L,0L)));target.size=v(input,"size",1);if(target instanceof Scenery){Scenery s=(Scenery)target;s.type=v(input,"kind",10);s.rotation=v(input,"rotation",0);List dim=(List)input.getOrDefault("dimensions",Arrays.asList(1L,1L));s.definition.sizeX=n(dim.get(0));s.definition.sizeY=n(dim.get(1));s.definition.walkingFlag=v(input,"walkingFlag",0);if(input.containsKey("definition")&&input.get("definition")==null)s.definition=null;}}events=new ArrayList<>();invocation=null;Object result=null;String error=null;try{Pathfinder f=input.containsKey("finder")&&input.get("finder")==null?null:new Pathfinder(v(input,"finder",0));boolean near=!Boolean.FALSE.equals(input.get("near"));String mode=(String)input.getOrDefault("mode","entity");Path p;switch(mode){case"entityDefault":p=Pathfinder.find((Entity)mover,target);break;case"water":p=Pathfinder.findWater((Entity)mover,target,near,f);break;case"explicit":p=Pathfinder.find((Entity)mover,target,near,f,supplier(input.get("supplier")));break;case"start":p=Pathfinder.find(loc(input.getOrDefault("start",Arrays.asList(3207L,3216L,0L))),v(input,"moverSize",1),target,near,f,supplier(input.get("supplier")));break;case"locationDefault":p=Pathfinder.find(mover==null?null:mover.location,target);break;case"locationSize":p=Pathfinder.find(mover==null?null:mover.location,target,v(input,"moverSize",1));break;case"locationFinder":p=Pathfinder.find(mover==null?null:mover.location,target,near,f);break;default:p=Pathfinder.find((Entity)mover,target,near,f);}result=p.value;}catch(NullPointerException e){error="Null";}catch(Failure e){error="Binding";}Map<String,Object> out=new TreeMap<>();out.put("result",result);out.put("invocation",invocation);out.put("events",events);out.put("error",error);out.put("mover",mover==null?null:coord(mover.location));out.put("target",target==null?null:coord(target.location));return out;}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);Object e=evaluate();input.put("expected",e);System.out.println(JSONValue.toJSONString(input));}}}
}
